#!/usr/bin/env python3
"""Assemble presentation-only terminology projections from canonical SQL."""
from pathlib import Path
import migration_inputs

ROOT = Path(__file__).resolve().parents[1]
SOURCES = (
    'eshop/order_item_terminology.sql',
    'sale_opening_notifications/settings.sql',
    'eshop_waitlist/order_overview.sql',
    'occasion_setup/sale_status.sql',
    'scanning/sessions.sql',
)
TARGET = ROOT / 'supabase/migrations/20261114233000_order_item_terminology.sql'
migration_inputs.write_text(TARGET,
    '-- Generated by automation/assemble-order-item-terminology-migration.py\nBEGIN;\n'
    + ''.join(f'\n-- Source: database/functions/{name}\n'
              + (ROOT / 'database/functions' / name).read_text() for name in SOURCES)
    + '\nCOMMIT;\n')
